// Suggested assessments for pairs of subcharacteristics.
// Key: QW.pairKey(a, b), i.e. both clause numbers in numeric order, joined by "|".
// rel: "support" | "neutral" | "conflict" | "both"
// Texts: support (why they support each other), conflict (why they conflict), neutral (why there is hardly a link).
// "both" has a support text and a conflict text. 40 subcharacteristics give 780 pairs;
// covered so far: the three subcharacteristics of 3.2 Performance efficiency against all others.
"use strict";
window.QW = window.QW || {};

QW.suggestions = {
  // ---------- 3.2.1 Time behaviour ----------
  "3.1.1|3.2.1": { rel: "conflict",
    conflict: { en: "Every additional function makes screens, queries and start-up heavier. Feature-rich pages load more data and respond more slowly.",
                de: "Jede zusätzliche Funktion macht Masken, Abfragen und den Start schwerer. Funktionsreiche Seiten laden mehr Daten und reagieren langsamer." } },
  "3.1.2|3.2.1": { rel: "conflict",
    conflict: { en: "Exact calculations and strict consistency cost time. Faster approaches such as caching, approximation or eventual consistency can deliver outdated or less precise results.",
                de: "Exakte Berechnungen und strikte Konsistenz kosten Zeit. Schnellere Wege wie Caching, Näherungsverfahren oder Eventual Consistency können veraltete oder ungenauere Ergebnisse liefern." } },
  "3.1.3|3.2.1": { rel: "support",
    support: { en: "Fewer unnecessary steps mean fewer page loads and round trips – the whole task is done faster, even if each single response stays the same.",
               de: "Weniger überflüssige Schritte bedeuten weniger Seitenaufrufe und Round Trips – die ganze Aufgabe ist schneller erledigt, auch wenn jede einzelne Antwort gleich schnell bleibt." } },
  "3.2.1|3.2.3": { rel: "both",
    support: { en: "Short processing times free threads, connections and memory sooner, so the same hardware handles more requests.",
               de: "Kurze Verarbeitungszeiten geben Threads, Verbindungen und Speicher früher frei, sodass dieselbe Hardware mehr Requests schafft." },
    conflict: { en: "Close to the capacity limit, queues grow and response times rise sharply. Designs that maximise throughput, such as batching, make the single request wait longer.",
                de: "Nahe der Kapazitätsgrenze wachsen die Warteschlangen und die Antwortzeiten steigen stark. Entwürfe, die den Durchsatz maximieren, etwa Batching, lassen den einzelnen Request länger warten." } },
  "3.2.1|3.3.1": { rel: "conflict",
    conflict: { en: "A product that grabs as much CPU, memory and network as possible to be fast slows down its neighbours – and noisy neighbours slow it down in turn.",
                de: "Ein Produkt, das sich für hohes Tempo möglichst viel CPU, Speicher und Netz nimmt, bremst seine Nachbarn – und laute Nachbarn bremsen umgekehrt das Produkt." } },
  "3.2.1|3.3.2": { rel: "conflict",
    conflict: { en: "Calls to other systems, conversions between formats and verbose standard formats add latency, and the response time depends on the slowest partner.",
                de: "Aufrufe anderer Systeme, Konvertierungen zwischen Formaten und ausführliche Standardformate kosten Latenz, und die Antwortzeit hängt vom langsamsten Partner ab." } },
  "3.2.1|3.4.1": { rel: "support",
    support: { en: "A start page that appears at once lets users see quickly what the product offers; a slow first impression makes many of them leave before they have seen anything.",
               de: "Eine Startseite, die sofort erscheint, zeigt schnell, was das Produkt bietet; ein langsamer erster Eindruck lässt viele gehen, bevor sie etwas gesehen haben." } },
  "3.2.1|3.4.2": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Immediate feedback makes it a little easier to learn by trying, but learnability depends mainly on the design of the interaction.",
               de: "Kaum ein direkter Zusammenhang. Sofortige Rückmeldung erleichtert das Ausprobieren etwas, Erlernbarkeit hängt aber vor allem von der Gestaltung der Interaktion ab." } },
  "3.2.1|3.4.3": { rel: "support",
    support: { en: "A product is easy to control only if it reacts quickly: below about 100 ms an action feels direct, after a few seconds users lose the thread.",
               de: "Ein Produkt ist nur dann gut steuerbar, wenn es schnell reagiert: Unter etwa 100 ms wirkt eine Aktion unmittelbar, nach einigen Sekunden verlieren Nutzende den Faden." } },
  "3.2.1|3.4.4": { rel: "both",
    support: { en: "Fast inline validation shows a mistake while the user is still in the field, before the error can spread.",
               de: "Schnelle Prüfung direkt im Formular zeigt einen Fehler, solange man noch im Feld ist, bevor er sich auswirken kann." },
    conflict: { en: "Checks on the server, confirmation steps and plausibility rules add waiting time to every input.",
                de: "Prüfungen auf dem Server, Bestätigungsschritte und Plausibilitätsregeln verlängern jede Eingabe um Wartezeit." } },
  "3.2.1|3.4.5": { rel: "both",
    support: { en: "A fast product is pleasant to use; waiting is one of the strongest reasons why users give up.",
               de: "Ein schnelles Produkt macht Freude; Warten ist einer der stärksten Gründe, warum Nutzende aufgeben." },
    conflict: { en: "Large images, animations, video and web fonts that make a product attractive also make it load more slowly.",
                de: "Große Bilder, Animationen, Videos und Webfonts, die ein Produkt attraktiv machen, lassen es auch langsamer laden." } },
  "3.2.1|3.4.6": { rel: "support",
    support: { en: "Pages that stay fast on slow mobile networks and old devices make the product usable for more people. Response times should therefore also be measured on weak devices.",
               de: "Seiten, die auch mit langsamem Mobilnetz und auf alten Geräten schnell bleiben, machen das Produkt für mehr Menschen nutzbar. Antwortzeiten sollten deshalb auch auf schwachen Geräten gemessen werden." } },
  "3.2.1|3.4.7": { rel: "both",
    support: { en: "Quick responses also help users of assistive technology, who often need more interaction steps for the same task.",
               de: "Schnelle Antworten helfen auch Nutzenden mit Hilfstechnologien, die für dieselbe Aufgabe oft mehr Interaktionsschritte brauchen." },
    conflict: { en: "Speech recognition, live captions or text-to-speech add processing time; short time-outs, set for performance, can lock out users who need more time.",
                de: "Spracherkennung, Live-Untertitel oder Sprachausgabe kosten Verarbeitungszeit; kurze Timeouts, die der Performance dienen, können Nutzende aussperren, die mehr Zeit brauchen." } },
  "3.2.1|3.4.8": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Explanations next to a field cost almost no time; long help pages are loaded only when they are needed.",
               de: "Kaum ein direkter Zusammenhang. Erklärungen neben einem Feld kosten fast keine Zeit; lange Hilfeseiten werden erst geladen, wenn sie gebraucht werden." } },
  "3.2.1|3.5.1": { rel: "both",
    support: { en: "Faults such as time-outs, retries and restarts make the product slow for the affected users.",
               de: "Fehler wie Timeouts, Wiederholungen und Neustarts machen das Produkt für die Betroffenen langsam." },
    conflict: { en: "Optimisations such as caches, parallel processing or hand-tuned code are a typical source of faults: race conditions, stale data, subtle bugs.",
                de: "Optimierungen wie Caches, Parallelverarbeitung oder handoptimierter Code sind eine typische Fehlerquelle: Race Conditions, veraltete Daten, subtile Bugs." } },
  "3.2.1|3.5.2": { rel: "both",
    support: { en: "A product that responds too slowly counts as unavailable for its users – time-outs turn slowness into outages. Additional instances for availability also share the load.",
               de: "Ein Produkt, das zu langsam antwortet, gilt für seine Nutzenden als nicht verfügbar – Timeouts machen aus Langsamkeit Ausfälle. Zusätzliche Instanzen für die Verfügbarkeit teilen sich außerdem die Last." },
    conflict: { en: "Synchronous replication to a second site and health checks add latency to every write.",
                de: "Synchrone Replikation an einen zweiten Standort und Health Checks verlängern jeden Schreibzugriff." } },
  "3.2.1|3.5.3": { rel: "conflict",
    conflict: { en: "Fault tolerance needs replicas that agree (quorum), retries and time-outs; all of them add latency, and a failover itself causes a pause.",
                de: "Fehlertoleranz braucht Repliken, die sich einigen (Quorum), Wiederholungen und Timeouts; alles kostet Latenz, und ein Failover selbst verursacht eine Pause." } },
  "3.2.1|3.5.4": { rel: "conflict",
    conflict: { en: "Write-ahead logs, frequent snapshots and synchronous backups slow down writes – the smaller the allowed data loss (RPO), the bigger the effect.",
                de: "Write-Ahead-Logs, häufige Snapshots und synchrone Sicherungen bremsen Schreibzugriffe – je kleiner der erlaubte Datenverlust (RPO), desto stärker." } },
  "3.2.1|3.6.1": { rel: "conflict",
    conflict: { en: "Encryption, TLS handshakes and permission checks cost time; personalised, confidential data cannot be served from a shared cache.",
                de: "Verschlüsselung, TLS-Handshakes und Berechtigungsprüfungen kosten Zeit; persönliche, vertrauliche Daten können nicht aus einem gemeinsamen Cache kommen." } },
  "3.2.1|3.6.2": { rel: "conflict",
    conflict: { en: "Transactions, locks, checksums and signatures protect the data but make every change take longer.",
                de: "Transaktionen, Sperren, Prüfsummen und Signaturen schützen die Daten, machen aber jede Änderung langsamer." } },
  "3.2.1|3.6.3": { rel: "conflict",
    conflict: { en: "Digital signatures and calls to a timestamping service lie in the path of the request and add latency.",
                de: "Digitale Signaturen und Aufrufe eines Zeitstempeldienstes liegen im Weg des Requests und kosten Latenz." } },
  "3.2.1|3.6.4": { rel: "conflict",
    conflict: { en: "Every action has to be written to the audit log. The effect is small if the log is written asynchronously – but then entries can get lost in a crash.",
                de: "Jede Aktion muss ins Audit-Log. Der Effekt ist klein, wenn asynchron geschrieben wird – dann können bei einem Absturz aber Einträge verloren gehen." } },
  "3.2.1|3.6.5": { rel: "conflict",
    conflict: { en: "A second factor, token validation and calls to the identity provider add waiting time, especially at login.",
                de: "Ein zweiter Faktor, Token-Prüfung und Aufrufe beim Identity Provider kosten Wartezeit, vor allem bei der Anmeldung." } },
  "3.2.1|3.6.6": { rel: "both",
    support: { en: "Rate limiting and DDoS protection keep the response times stable for legitimate users while an attack is running.",
               de: "Rate Limiting und DDoS-Schutz halten die Antwortzeiten für berechtigte Nutzende stabil, während ein Angriff läuft." },
    conflict: { en: "A web application firewall inspects every request and adds a little latency.",
                de: "Eine Web Application Firewall prüft jeden Request und kostet etwas Latenz." } },
  "3.2.1|3.7.1": { rel: "both",
    support: { en: "A slow module can be found, optimised or scaled on its own, without touching the rest.",
               de: "Ein langsames Modul lässt sich einzeln finden, optimieren oder skalieren, ohne den Rest anzufassen." },
    conflict: { en: "Network calls between services, serialisation and extra hops add latency compared with method calls in one process.",
                de: "Netzaufrufe zwischen Services, Serialisierung und zusätzliche Hops kosten Latenz gegenüber Methodenaufrufen in einem Prozess." } },
  "3.2.1|3.7.2": { rel: "conflict",
    conflict: { en: "Generic, configurable components are usually slower than a solution made for one purpose.",
                de: "Generische, konfigurierbare Komponenten sind meist langsamer als eine Lösung für genau einen Zweck." } },
  "3.2.1|3.7.3": { rel: "both",
    support: { en: "Profiling, tracing and metrics show where the time is lost – without them, optimisation is guesswork.",
               de: "Profiling, Tracing und Metriken zeigen, wo die Zeit verloren geht – ohne sie ist Optimieren Raten." },
    conflict: { en: "Detailed instrumentation and logging cost time in every request.",
                de: "Ausführliche Instrumentierung und Logging kosten in jedem Request Zeit." } },
  "3.2.1|3.7.4": { rel: "both",
    support: { en: "Code that is easy to change can be optimised where measurements show a bottleneck.",
               de: "Leicht änderbarer Code lässt sich dort optimieren, wo Messungen einen Engpass zeigen." },
    conflict: { en: "Layers, indirection and configuration cost time; hand-optimised code is often hard to understand and to change.",
                de: "Schichten, Indirektion und Konfiguration kosten Zeit; handoptimierter Code ist oft schwer zu verstehen und zu ändern." } },
  "3.2.1|3.7.5": { rel: "support",
    support: { en: "Load tests and benchmarks make response times measurable and stop regressions before release; this needs a product that can be tested automatically.",
               de: "Lasttests und Benchmarks machen Antwortzeiten messbar und halten Verschlechterungen vor dem Release auf; dafür muss sich das Produkt automatisiert testen lassen." } },
  "3.2.1|3.8.1": { rel: "conflict",
    conflict: { en: "Abstraction layers, virtual machines and cross-platform frameworks are slower than native code and cannot use the special features of one platform.",
                de: "Abstraktionsschichten, virtuelle Maschinen und Cross-Platform-Frameworks sind langsamer als nativer Code und können Besonderheiten einer Plattform nicht nutzen." } },
  "3.2.1|3.8.2": { rel: "both",
    support: { en: "Scaling out keeps response times stable when the load grows.",
               de: "Scale-out hält die Antwortzeiten stabil, wenn die Last wächst." },
    conflict: { en: "Distributed coordination, network hops and cold starts of new instances add latency.",
                de: "Verteilte Koordination, Netz-Hops und Kaltstarts neuer Instanzen kosten Latenz." } },
  "3.2.1|3.8.3": { rel: "neutral",
    neutral: { en: "Hardly any direct link. How easily a product can be installed says little about how fast it runs afterwards.",
               de: "Kaum ein direkter Zusammenhang. Wie leicht sich ein Produkt installieren lässt, sagt wenig darüber, wie schnell es danach läuft." } },
  "3.2.1|3.8.4": { rel: "both",
    support: { en: "A replaceable component can be exchanged for a faster one.",
               de: "Eine austauschbare Komponente lässt sich gegen eine schnellere tauschen." },
    conflict: { en: "Staying with standard interfaces means giving up fast, product-specific features.",
                de: "Wer bei Standardschnittstellen bleibt, verzichtet auf schnelle, produktspezifische Funktionen." } },
  "3.2.1|3.9.1": { rel: "both",
    support: { en: "A constraint helps only if it acts in time – fast and guaranteed reaction times are a safety requirement.",
               de: "Eine Begrenzung hilft nur, wenn sie rechtzeitig greift – schnelle und garantierte Reaktionszeiten sind eine Safety-Anforderung." },
    conflict: { en: "Safety checks in the control path cost time, and safety-critical systems prefer predictable worst-case times to fast average times; caches and dynamic optimisations are often switched off.",
                de: "Sicherheitsprüfungen im Steuerungspfad kosten Zeit, und sicherheitskritische Systeme ziehen vorhersagbare Worst-Case-Zeiten schnellen Durchschnittszeiten vor; Caches und dynamische Optimierungen werden oft abgeschaltet." } },
  "3.2.1|3.9.2": { rel: "both",
    support: { en: "Risks must be identified while there is still time to react; this needs fast processing of sensor data.",
               de: "Risiken müssen erkannt werden, solange noch Zeit zum Reagieren bleibt; dafür muss die Verarbeitung der Sensordaten schnell sein." },
    conflict: { en: "Continuous analysis competes with the main function for CPU time.",
                de: "Die dauernde Auswertung konkurriert mit der eigentlichen Funktion um Rechenzeit." } },
  "3.2.1|3.9.3": { rel: "support",
    support: { en: "The switch to the safe state must happen in time; short and guaranteed reaction times, for example with a watchdog, support fail-safe behaviour.",
               de: "Der Wechsel in den sicheren Zustand muss rechtzeitig passieren; kurze und garantierte Reaktionszeiten, etwa mit einem Watchdog, unterstützen Fail-safe." } },
  "3.2.1|3.9.4": { rel: "support",
    support: { en: "A warning is useful only if it comes early enough; slow processing eats up the time that operators need to react.",
               de: "Eine Warnung nützt nur, wenn sie früh genug kommt; langsame Verarbeitung frisst die Zeit, die das Bedienpersonal zum Reagieren braucht." } },
  "3.2.1|3.9.5": { rel: "neutral",
    neutral: { en: "Hardly any direct link – except that every new component can change the timing, so the worst-case reaction times have to be checked again after integration.",
               de: "Kaum ein direkter Zusammenhang – außer dass jede neue Komponente das Zeitverhalten ändern kann; die Worst-Case-Reaktionszeiten müssen nach der Integration erneut geprüft werden." } },

  // ---------- 3.2.2 Resource utilization ----------
  "3.1.1|3.2.2": { rel: "both",
    support: { en: "A complete product saves the extra tools, exports and manual workarounds that users otherwise run next to it.",
               de: "Ein vollständiges Produkt spart Zusatzwerkzeuge, Exporte und Umwege von Hand, die Nutzende sonst nebenher betreiben." },
    conflict: { en: "Every additional function costs code, memory, storage and often background activity. Feature-rich products tend to need bigger hardware; leaving out rarely used features saves resources.",
                de: "Jede zusätzliche Funktion kostet Code, Speicher und oft Hintergrundaktivität. Funktionsreiche Produkte brauchen meist größere Hardware; selten genutzte Funktionen wegzulassen spart Ressourcen." } },
  "3.1.2|3.2.2": { rel: "both",
    support: { en: "Wrong results lead to corrections, reruns and repeated transfers – all of them consume resources a second time.",
               de: "Falsche Ergebnisse führen zu Korrekturen, Wiederholungsläufen und erneuten Übertragungen – alles verbraucht Ressourcen ein zweites Mal." },
    conflict: { en: "Higher precision costs computing power: exact decimal arithmetic instead of floating point, more iterations, finer simulation grids or larger AI models.",
                de: "Höhere Genauigkeit kostet Rechenleistung: exakte Dezimalarithmetik statt Gleitkomma, mehr Iterationen, feinere Simulationsgitter oder größere KI-Modelle." } },
  "3.1.3|3.2.2": { rel: "support",
    support: { en: "Fewer unnecessary steps mean fewer page loads, requests and database queries per task – and less waiting time on the user's device.",
               de: "Weniger überflüssige Schritte bedeuten weniger Seitenaufrufe, Requests und Datenbankabfragen pro Aufgabe – und weniger Wartezeit auf dem Endgerät." } },
  "3.2.1|3.2.2": { rel: "both",
    support: { en: "Efficient algorithms, a sensible data model and caching make a function faster and cheaper at the same time.",
               de: "Effiziente Algorithmen, ein sinnvolles Datenmodell und Caching machen eine Funktion zugleich schneller und sparsamer." },
    conflict: { en: "Speed is often bought with resources: over-provisioned servers, instances kept warm, prefetching, large in-memory caches and parallel work that is thrown away.",
                de: "Tempo wird oft mit Ressourcen erkauft: überdimensionierte Server, warm gehaltene Instanzen, Prefetching, große Caches im Arbeitsspeicher und parallele Arbeit, die verworfen wird." } },
  "3.2.2|3.2.3": { rel: "both",
    support: { en: "A product that needs few resources per request reaches a higher capacity on the same hardware.",
               de: "Ein Produkt, das pro Request wenig Ressourcen braucht, erreicht auf derselben Hardware eine höhere Kapazität." },
    conflict: { en: "Capacity that is reserved for rare peaks stands idle most of the time and still consumes energy and embodied carbon.",
                de: "Kapazität, die für seltene Spitzen vorgehalten wird, steht die meiste Zeit leer und verbraucht trotzdem Energie und graue Emissionen (Embodied Carbon)." } },
  "3.2.2|3.3.1": { rel: "support",
    support: { en: "A product that uses few resources leaves more for the other products in the shared environment and disturbs them less.",
               de: "Ein Produkt, das wenig Ressourcen braucht, lässt den anderen Produkten in der gemeinsamen Umgebung mehr übrig und stört sie weniger." } },
  "3.2.2|3.3.2": { rel: "both",
    support: { en: "Products that can share data avoid duplicate storage, manual re-entry and parallel systems for the same information.",
               de: "Produkte, die Daten austauschen können, vermeiden doppelte Speicherung, erneute Eingabe von Hand und Parallelsysteme für dieselben Informationen." },
    conflict: { en: "Standard formats such as XML or JSON, adapters and conversions cost more CPU time and bandwidth than a compact proprietary format.",
                de: "Standardformate wie XML oder JSON, Adapter und Konvertierungen kosten mehr Rechenzeit und Bandbreite als ein kompaktes proprietäres Format." } },
  "3.2.2|3.4.1": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Demo videos and large images on the start page cost some data, but that is a question of design, not of recognizability.",
               de: "Kaum ein direkter Zusammenhang. Demovideos und große Bilder auf der Startseite kosten etwas Datenvolumen, das ist aber eine Frage der Gestaltung, nicht der Erkennbarkeit." } },
  "3.2.2|3.4.2": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Learning aids such as videos cost some data, and users who learn quickly cause fewer wasted attempts – both effects are small.",
               de: "Kaum ein direkter Zusammenhang. Lernhilfen wie Videos kosten etwas Datenvolumen, und wer schnell lernt, verursacht weniger Fehlversuche – beide Effekte sind klein." } },
  "3.2.2|3.4.3": { rel: "both",
    support: { en: "Easy operation leads to fewer wrong inputs, fewer repeated actions and shorter sessions.",
               de: "Leichte Bedienung führt zu weniger Fehleingaben, weniger wiederholten Aktionen und kürzeren Sitzungen." },
    conflict: { en: "Comfort features cost resources: a live search that sends a request on every keystroke, animations, a long undo history.",
                de: "Komfortfunktionen kosten Ressourcen: eine Live-Suche, die bei jedem Tastendruck einen Request schickt, Animationen, eine lange Undo-Historie." } },
  "3.2.2|3.4.4": { rel: "support",
    support: { en: "Errors that are prevented do not have to be processed, corrected and run again – for example a large print job or a batch run with wrong parameters.",
               de: "Verhinderte Fehler müssen nicht verarbeitet, korrigiert und erneut ausgeführt werden – etwa ein großer Druckauftrag oder ein Batch-Lauf mit falschen Parametern." } },
  "3.2.2|3.4.5": { rel: "conflict",
    conflict: { en: "Engagement often relies on high-resolution images, animations, video and autoplay. Designs that keep users as long as possible also increase usage time and energy on devices, networks and servers.",
                de: "Engagement setzt oft auf hochaufgelöste Bilder, Animationen, Videos und Autoplay. Gestaltung, die Nutzende möglichst lange hält, verlängert außerdem die Nutzungszeit und damit den Energieverbrauch auf Endgeräten, im Netz und auf Servern." } },
  "3.2.2|3.4.6": { rel: "both",
    support: { en: "A lightweight product also runs on old devices and slow or expensive mobile connections – this makes it usable for people with little money and extends the life of devices.",
               de: "Ein schlankes Produkt läuft auch auf alten Geräten und mit langsamen oder teuren Mobilverbindungen – das macht es für Menschen mit wenig Geld nutzbar und verlängert die Lebensdauer der Geräte." },
    conflict: { en: "Several languages, plain-language versions and alternative formats need more storage and maintenance.",
                de: "Mehrere Sprachen, Texte in Leichter Sprache und alternative Formate brauchen mehr Speicher und Pflege." } },
  "3.2.2|3.4.7": { rel: "both",
    support: { en: "Simple, semantic HTML without heavy scripts is good for screen readers and needs little data and computing power.",
               de: "Einfaches, semantisches HTML ohne schwere Skripte ist gut für Screenreader und braucht wenig Daten und Rechenleistung." },
    conflict: { en: "Alternative channels such as captions, audio description, voice input or eye tracking need additional processing and storage.",
                de: "Alternative Kanäle wie Untertitel, Audiodeskription, Spracheingabe oder Blicksteuerung brauchen zusätzliche Verarbeitung und Speicher." } },
  "3.2.2|3.4.8": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Help texts next to a field cost almost nothing; at most, users who understand the product at once cause fewer detours.",
               de: "Kaum ein direkter Zusammenhang. Hilfetexte neben einem Feld kosten fast nichts; allenfalls verursachen Nutzende, die das Produkt sofort verstehen, weniger Umwege." } },
  "3.2.2|3.5.1": { rel: "support",
    support: { en: "Faults cause retries, crashes, restarts and repeated computations; memory leaks and endless loops waste resources directly.",
               de: "Fehler verursachen Wiederholungen, Abstürze, Neustarts und doppelte Berechnungen; Speicherlecks und Endlosschleifen verschwenden Ressourcen direkt." } },
  "3.2.2|3.5.2": { rel: "conflict",
    conflict: { en: "Every additional nine needs redundancy: standby systems, a second data centre, spare capacity. This hardware runs and consumes energy even when nothing fails.",
                de: "Jede zusätzliche Neun braucht Redundanz: Standby-Systeme, ein zweites Rechenzentrum, Reservekapazität. Diese Hardware läuft und verbraucht Energie, auch wenn nichts ausfällt." } },
  "3.2.2|3.5.3": { rel: "conflict",
    conflict: { en: "Fault tolerance means replicas, redundant components and retries – the product does the same work several times or keeps resources ready for it.",
                de: "Fehlertoleranz heißt Repliken, redundante Komponenten und Wiederholungsversuche – das Produkt erledigt dieselbe Arbeit mehrfach oder hält Ressourcen dafür bereit." } },
  "3.2.2|3.5.4": { rel: "conflict",
    conflict: { en: "Backups, snapshots, transaction logs and replicas take storage and energy; the shorter the allowed data loss (RPO), the more often they run.",
                de: "Backups, Snapshots, Transaktionslogs und Repliken kosten Speicher und Energie; je kleiner der erlaubte Datenverlust (RPO), desto häufiger laufen sie." } },
  "3.2.2|3.6.1": { rel: "both",
    support: { en: "Data minimisation helps both: data that is not collected or is deleted early needs neither protection nor storage.",
               de: "Datensparsamkeit hilft beiden: Daten, die nicht erhoben oder früh gelöscht werden, brauchen weder Schutz noch Speicher." },
    conflict: { en: "Encryption, TLS handshakes and key management cost computing power – usually little, with hardware support for AES almost nothing.",
                de: "Verschlüsselung, TLS-Handshakes und Schlüsselverwaltung kosten Rechenleistung – meist wenig, mit Hardware-Unterstützung für AES fast nichts." } },
  "3.2.2|3.6.2": { rel: "conflict",
    conflict: { en: "Checksums, hashes, signatures and write-ahead logs cost computing time and storage. The effect is usually small.",
                de: "Prüfsummen, Hashes, Signaturen und Write-Ahead-Logs kosten Rechenzeit und Speicher. Der Effekt ist meist klein." } },
  "3.2.2|3.6.3": { rel: "conflict",
    conflict: { en: "Proofs have to be created and kept: digital signatures, trusted timestamps and archives that often must be stored for many years.",
                de: "Nachweise müssen erzeugt und aufbewahrt werden: digitale Signaturen, qualifizierte Zeitstempel und Archive, die oft viele Jahre lang gespeichert bleiben müssen." } },
  "3.2.2|3.6.4": { rel: "conflict",
    conflict: { en: "Audit logs grow with every action and often have to be kept for years. Clear retention periods and logging only what is needed keep the cost low.",
                de: "Audit-Logs wachsen mit jeder Aktion und müssen oft jahrelang aufbewahrt werden. Klare Aufbewahrungsfristen und nur das Nötige zu protokollieren halten den Aufwand klein." } },
  "3.2.2|3.6.5": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Checking certificates and a second factor costs very little compared with the actual work of a product.",
               de: "Kaum ein direkter Zusammenhang. Zertifikatsprüfung und ein zweiter Faktor kosten im Vergleich zur eigentlichen Arbeit eines Produkts sehr wenig." } },
  "3.2.2|3.6.6": { rel: "both",
    support: { en: "Rate limiting and blocking bots also stop the waste of resources: a denial-of-service attack is nothing else than forced resource consumption.",
               de: "Rate Limiting und das Abweisen von Bots stoppen auch Verschwendung: Ein Denial-of-Service-Angriff ist nichts anderes als erzwungener Ressourcenverbrauch." },
    conflict: { en: "Web application firewalls, intrusion detection and permanent security scans run all the time and need their own capacity.",
                de: "Web Application Firewalls, Intrusion Detection und dauernde Sicherheitsscans laufen ständig und brauchen eigene Kapazität." } },
  "3.2.2|3.7.1": { rel: "both",
    support: { en: "Modules can be measured, optimised, scaled or replaced one by one – the hotspot gets attention, the rest stays small.",
               de: "Module lassen sich einzeln messen, optimieren, skalieren oder austauschen – der Hotspot bekommt Aufmerksamkeit, der Rest bleibt klein." },
    conflict: { en: "Fine-grained services cost overhead: network calls instead of method calls, serialisation, one runtime and one database per service.",
                de: "Feingranulare Services kosten Overhead: Netzaufrufe statt Methodenaufrufe, Serialisierung, eine Laufzeitumgebung und eine Datenbank pro Service." } },
  "3.2.2|3.7.2": { rel: "both",
    support: { en: "Reuse avoids developing, running and storing the same thing twice.",
               de: "Wiederverwendung vermeidet, dasselbe doppelt zu entwickeln, zu betreiben und zu speichern." },
    conflict: { en: "Generic, configurable components carry code and features that a single use does not need – a large framework for a small task.",
                de: "Generische, konfigurierbare Komponenten bringen Code und Funktionen mit, die ein einzelner Einsatz nicht braucht – ein großes Framework für eine kleine Aufgabe." } },
  "3.2.2|3.7.3": { rel: "both",
    support: { en: "Only what is measured can be optimised: profiling, metrics and energy measurement show where resources are wasted.",
               de: "Nur was gemessen wird, lässt sich optimieren: Profiling, Metriken und Energiemessung zeigen, wo Ressourcen verschwendet werden." },
    conflict: { en: "Detailed logging, tracing and metrics produce large amounts of data that have to be transferred, stored and analysed.",
                de: "Ausführliches Logging, Tracing und Metriken erzeugen große Datenmengen, die übertragen, gespeichert und ausgewertet werden müssen." } },
  "3.2.2|3.7.4": { rel: "both",
    support: { en: "Code that is easy to change can be optimised later, when measurements show where it is worth it.",
               de: "Leicht änderbarer Code lässt sich später optimieren, wenn Messungen zeigen, wo es sich lohnt." },
    conflict: { en: "Abstraction layers, indirection and configurability cost runtime; hand-optimised code is often hard to change.",
                de: "Abstraktionsschichten, Indirektion und Konfigurierbarkeit kosten Laufzeit; handoptimierter Code ist oft schwer zu ändern." } },
  "3.2.2|3.7.5": { rel: "both",
    support: { en: "Performance and energy tests make resource use checkable and stop regressions before they go into production.",
               de: "Performance- und Energietests machen den Ressourcenverbrauch prüfbar und halten Verschlechterungen auf, bevor sie in Produktion gehen." },
    conflict: { en: "Large test suites that run on every commit, plus separate test environments, consume a lot of computing time and energy.",
                de: "Große Testsuiten, die bei jedem Commit laufen, und eigene Testumgebungen verbrauchen viel Rechenzeit und Energie." } },
  "3.2.2|3.8.1": { rel: "both",
    support: { en: "A product that runs on other or older hardware extends the life of devices and saves embodied carbon.",
               de: "Ein Produkt, das auf anderer oder älterer Hardware läuft, verlängert die Lebensdauer von Geräten und spart graue Emissionen (Embodied Carbon)." },
    conflict: { en: "Portability layers such as virtual machines, cross-platform frameworks or bundled runtimes add overhead compared with a native implementation.",
                de: "Portabilitätsschichten wie virtuelle Maschinen, Cross-Platform-Frameworks oder mitgelieferte Laufzeitumgebungen kosten gegenüber einer nativen Umsetzung zusätzlich." } },
  "3.2.2|3.8.2": { rel: "both",
    support: { en: "A product that can scale down releases servers when the load is low – resources follow the real demand.",
               de: "Ein Produkt, das herunterskalieren kann, gibt bei geringer Last Server frei – die Ressourcen folgen dem tatsächlichen Bedarf." },
    conflict: { en: "Scale-out architectures need coordination, load balancers and data replication, and they invite generous headroom.",
                de: "Scale-out-Architekturen brauchen Koordination, Load Balancer und Datenreplikation und verleiten zu großzügigen Reserven." } },
  "3.2.2|3.8.3": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Lean packages install quickly and use little storage, but installers that bring their own runtime are larger – this depends on the design.",
               de: "Kaum ein direkter Zusammenhang. Schlanke Pakete installieren schnell und brauchen wenig Speicher, Installer mit eigener Laufzeitumgebung sind aber größer – das hängt von der Gestaltung ab." } },
  "3.2.2|3.8.4": { rel: "support",
    support: { en: "Replaceable components make it possible to switch to a more efficient alternative; standard formats avoid lock-in to an inefficient platform.",
               de: "Austauschbare Komponenten erlauben den Wechsel zu einer effizienteren Alternative; Standardformate vermeiden die Bindung an eine ineffiziente Plattform." } },
  "3.2.2|3.9.1": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Safe limits are about hazards, not about resources; the checks themselves cost very little.",
               de: "Kaum ein direkter Zusammenhang. Sichere Grenzen betreffen Gefährdungen, nicht Ressourcen; die Prüfungen selbst kosten sehr wenig." } },
  "3.2.2|3.9.2": { rel: "conflict",
    conflict: { en: "Identifying risks needs continuous monitoring: many sensors, high sampling rates and analysis models that compute all the time.",
                de: "Risikoerkennung braucht dauernde Überwachung: viele Sensoren, hohe Abtastraten und Auswertungsmodelle, die ständig rechnen." } },
  "3.2.2|3.9.3": { rel: "both",
    support: { en: "The safe state is often a state with little activity – a machine that stops uses less energy than one that keeps running.",
               de: "Der sichere Zustand ist oft ein Zustand mit wenig Aktivität – eine Maschine, die anhält, verbraucht weniger als eine, die weiterläuft." },
    conflict: { en: "Safety-related designs often use redundant channels, for example two out of three controllers that compute the same result.",
                de: "Sicherheitsgerichtete Entwürfe nutzen oft redundante Kanäle, etwa zwei von drei Steuerungen, die dasselbe Ergebnis berechnen." } },
  "3.2.2|3.9.4": { rel: "neutral",
    neutral: { en: "Hardly any direct link. A warning is cheap; the effort lies in risk identification, which is a separate subcharacteristic.",
               de: "Kaum ein direkter Zusammenhang. Eine Warnung ist billig; der Aufwand liegt in der Risikoerkennung, einer eigenen Unterqualität." } },
  "3.2.2|3.9.5": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Isolating safety-critical parts, for example on a separate controller, can need some extra hardware, but this is a question of architecture, not of resource use in operation.",
               de: "Kaum ein direkter Zusammenhang. Sicherheitskritische Teile zu isolieren, etwa auf einer eigenen Steuerung, kann etwas zusätzliche Hardware brauchen, das ist aber eine Frage der Architektur, nicht des Ressourcenverbrauchs im Betrieb." } },

  // ---------- 3.2.3 Capacity ----------
  "3.1.1|3.2.3": { rel: "conflict",
    conflict: { en: "More functions share the same resources; heavy features such as reports or bulk exports take capacity away from the core business.",
                de: "Mehr Funktionen teilen sich dieselben Ressourcen; schwere Funktionen wie Reports oder Massenexporte nehmen dem Kerngeschäft Kapazität weg." } },
  "3.1.2|3.2.3": { rel: "conflict",
    conflict: { en: "Strict consistency with transactions and locks limits how many users can work in parallel; higher throughput often needs relaxed consistency.",
                de: "Strikte Konsistenz mit Transaktionen und Sperren begrenzt, wie viele parallel arbeiten können; mehr Durchsatz verlangt oft gelockerte Konsistenz." } },
  "3.1.3|3.2.3": { rel: "support",
    support: { en: "Fewer steps per task mean fewer requests per user – the same capacity serves more users.",
               de: "Weniger Schritte pro Aufgabe bedeuten weniger Requests pro Nutzer – dieselbe Kapazität reicht für mehr Nutzende." } },
  "3.2.3|3.3.1": { rel: "conflict",
    conflict: { en: "A product that reserves resources for its own peaks takes them away from its neighbours; quotas for co-existence in turn limit its maximum capacity.",
                de: "Ein Produkt, das Ressourcen für die eigenen Spitzen reserviert, nimmt sie seinen Nachbarn weg; Quotas für die Koexistenz begrenzen umgekehrt seine maximale Kapazität." } },
  "3.2.3|3.3.2": { rel: "both",
    support: { en: "Standard protocols such as HTTP make it possible to put load balancers, caches and CDNs in front of the product.",
               de: "Standardprotokolle wie HTTP erlauben, Load Balancer, Caches und CDNs vor das Produkt zu stellen." },
    conflict: { en: "If every request needs a partner system, the weakest partner limits the capacity of the whole chain.",
                de: "Braucht jeder Request ein Partnersystem, begrenzt der schwächste Partner die Kapazität der ganzen Kette." } },
  "3.2.3|3.4.1": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Capacity matters for how many users can work at the same time, not for whether they recognise the purpose of the product.",
               de: "Kaum ein direkter Zusammenhang. Kapazität betrifft, wie viele gleichzeitig arbeiten können, nicht, ob sie den Zweck des Produkts erkennen." } },
  "3.2.3|3.4.2": { rel: "neutral",
    neutral: { en: "Hardly any direct link between how quickly users learn the product and how many it can serve at once.",
               de: "Kaum ein direkter Zusammenhang zwischen der Frage, wie schnell Nutzende das Produkt lernen, und der Frage, wie viele es gleichzeitig bedienen kann." } },
  "3.2.3|3.4.3": { rel: "neutral",
    neutral: { en: "Hardly any direct link – as long as the product stays below its capacity limit. Above it, operation suffers from slow or failed responses.",
               de: "Kaum ein direkter Zusammenhang – solange das Produkt unter seiner Kapazitätsgrenze bleibt. Darüber leidet die Bedienung unter langsamen oder fehlgeschlagenen Antworten." } },
  "3.2.3|3.4.4": { rel: "neutral",
    neutral: { en: "Hardly any direct link. At most, protection against accidental mass actions, such as exporting all data at once, also protects the capacity.",
               de: "Kaum ein direkter Zusammenhang. Allenfalls schützt ein Schutz vor versehentlichen Massenaktionen, etwa dem Export aller Daten auf einmal, auch die Kapazität." } },
  "3.2.3|3.4.5": { rel: "conflict",
    conflict: { en: "Engaging content such as video, live updates and personalisation increases the load per user – and success brings more users at the same time.",
                de: "Ansprechende Inhalte wie Videos, Live-Updates und Personalisierung erhöhen die Last pro Nutzer – und Erfolg bringt mehr gleichzeitige Nutzende." } },
  "3.2.3|3.4.6": { rel: "neutral",
    neutral: { en: "Hardly any direct link. An inclusive product reaches more people, so the expected number of users should be planned with that in mind.",
               de: "Kaum ein direkter Zusammenhang. Ein inklusives Produkt erreicht mehr Menschen; die erwartete Zahl der Nutzenden sollte das berücksichtigen." } },
  "3.2.3|3.4.7": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Alternative formats need some storage, but they hardly change how many users the product can serve.",
               de: "Kaum ein direkter Zusammenhang. Alternative Formate brauchen etwas Speicher, ändern aber kaum, wie viele Nutzende das Produkt bedienen kann." } },
  "3.2.3|3.4.8": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Explanations in the user interface cost almost no capacity.",
               de: "Kaum ein direkter Zusammenhang. Erklärungen in der Oberfläche kosten fast keine Kapazität." } },
  "3.2.3|3.5.1": { rel: "both",
    support: { en: "Without faults such as memory or connection leaks, the capacity stays the same over weeks instead of slowly shrinking.",
               de: "Ohne Fehler wie Speicher- oder Verbindungslecks bleibt die Kapazität über Wochen gleich, statt langsam zu schrumpfen." },
    conflict: { en: "Running close to the capacity limit brings out rare faults: race conditions, time-outs, exhausted pools.",
                de: "Betrieb nahe der Kapazitätsgrenze bringt seltene Fehler ans Licht: Race Conditions, Timeouts, erschöpfte Pools." } },
  "3.2.3|3.5.2": { rel: "both",
    support: { en: "Enough capacity prevents outages through overload, for example on Black Friday or at the start of an online exam.",
               de: "Genug Kapazität verhindert Ausfälle durch Überlast, etwa am Black Friday oder zum Start einer Online-Prüfung." },
    conflict: { en: "Capacity kept for failover (N+1) must not be used for normal load – the usable capacity is smaller than the installed one.",
                de: "Kapazität, die für ein Failover (N+1) vorgehalten wird, darf nicht für die normale Last genutzt werden – die nutzbare Kapazität ist kleiner als die installierte." } },
  "3.2.3|3.5.3": { rel: "both",
    support: { en: "Spare capacity absorbs the failure of a node without overloading the rest.",
               de: "Reservekapazität fängt den Ausfall eines Knotens ab, ohne den Rest zu überlasten." },
    conflict: { en: "Replicas and retries use capacity themselves; under load, retries can grow into a retry storm that makes the overload worse.",
                de: "Repliken und Wiederholungen verbrauchen selbst Kapazität; unter Last können Wiederholungen zu einem Retry Storm werden, der die Überlast verschlimmert." } },
  "3.2.3|3.5.4": { rel: "conflict",
    conflict: { en: "Backups and replication use I/O and storage capacity; the larger the database grows, the longer a restore takes.",
                de: "Backups und Replikation verbrauchen I/O- und Speicherkapazität; je größer die Datenbank wird, desto länger dauert eine Wiederherstellung." } },
  "3.2.3|3.6.1": { rel: "conflict",
    conflict: { en: "Encryption costs CPU per request, and personalised confidential data cannot be served from shared caches – both reduce the throughput.",
                de: "Verschlüsselung kostet CPU pro Request, und persönliche vertrauliche Daten können nicht aus gemeinsamen Caches kommen – beides senkt den Durchsatz." } },
  "3.2.3|3.6.2": { rel: "conflict",
    conflict: { en: "Locks and transactions that protect the data limit how many changes can run in parallel.",
                de: "Sperren und Transaktionen, die die Daten schützen, begrenzen, wie viele Änderungen parallel laufen können." } },
  "3.2.3|3.6.3": { rel: "conflict",
    conflict: { en: "A central signature or timestamping service can become the bottleneck, and the archived proofs fill the storage over the years.",
                de: "Ein zentraler Signatur- oder Zeitstempeldienst kann zum Engpass werden, und die archivierten Nachweise füllen über die Jahre den Speicher." } },
  "3.2.3|3.6.4": { rel: "conflict",
    conflict: { en: "Audit logs need write throughput and storage capacity; at high load the log can become the limit.",
                de: "Audit-Logs brauchen Schreibdurchsatz und Speicherkapazität; bei hoher Last kann das Log zur Grenze werden." } },
  "3.2.3|3.6.5": { rel: "conflict",
    conflict: { en: "Every login goes through the identity provider and cryptographic checks; at peaks, such as the start of a ticket sale, the login is often the bottleneck.",
                de: "Jede Anmeldung läuft über den Identity Provider und kryptografische Prüfungen; bei Spitzen, etwa zum Start eines Ticketverkaufs, ist das Login oft der Engpass." } },
  "3.2.3|3.6.6": { rel: "both",
    support: { en: "Rate limiting and DDoS protection keep the capacity for legitimate users, and spare capacity helps to survive an attack.",
               de: "Rate Limiting und DDoS-Schutz halten die Kapazität für berechtigte Nutzende frei, und Reservekapazität hilft, einen Angriff zu überstehen." },
    conflict: { en: "Inspecting and filtering every request uses capacity itself.",
                de: "Jeden Request zu prüfen und zu filtern verbraucht selbst Kapazität." } },
  "3.2.3|3.7.1": { rel: "both",
    support: { en: "Modules can get exactly the capacity they need – the search service more, the admin area less.",
               de: "Module können genau die Kapazität bekommen, die sie brauchen – der Suchdienst mehr, der Admin-Bereich weniger." },
    conflict: { en: "Every separate service has its own overhead (runtime, connections, memory), which costs capacity.",
                de: "Jeder eigene Service hat eigenen Overhead (Laufzeitumgebung, Verbindungen, Speicher), der Kapazität kostet." } },
  "3.2.3|3.7.2": { rel: "conflict",
    conflict: { en: "A shared component used by many systems becomes a shared bottleneck: its capacity limits all of them.",
                de: "Eine gemeinsam genutzte Komponente wird zum gemeinsamen Engpass: Ihre Kapazität begrenzt alle Systeme, die sie nutzen." } },
  "3.2.3|3.7.3": { rel: "both",
    support: { en: "Capacity planning needs metrics: which resource fills up first, and when?",
               de: "Kapazitätsplanung braucht Metriken: Welche Ressource ist zuerst voll, und wann?" },
    conflict: { en: "Telemetry, logs and traces use network, storage and CPU capacity of their own.",
                de: "Telemetrie, Logs und Traces verbrauchen selbst Netz-, Speicher- und CPU-Kapazität." } },
  "3.2.3|3.7.4": { rel: "both",
    support: { en: "Limits that are configurable instead of hard-coded can be raised without a new release.",
               de: "Grenzen, die konfigurierbar statt fest im Code sind, lassen sich ohne neues Release anheben." },
    conflict: { en: "Measures for high capacity, such as sharding or denormalised data, make later changes more expensive.",
                de: "Maßnahmen für hohe Kapazität wie Sharding oder denormalisierte Daten machen spätere Änderungen teurer." } },
  "3.2.3|3.7.5": { rel: "support",
    support: { en: "Load and stress tests show where the limits really are; they need a product that can be tested automatically and a test environment close to production.",
               de: "Last- und Stresstests zeigen, wo die Grenzen wirklich liegen; dafür muss sich das Produkt automatisiert testen lassen, in einer Umgebung nahe an der Produktion." } },
  "3.2.3|3.8.1": { rel: "both",
    support: { en: "A product that runs on other hardware or with another cloud provider can move to bigger machines when it needs more capacity.",
               de: "Ein Produkt, das auf anderer Hardware oder bei einem anderen Cloud-Anbieter läuft, kann auf größere Maschinen umziehen, wenn es mehr Kapazität braucht." },
    conflict: { en: "Portability layers cost resources that are then missing for the actual work.",
                de: "Portabilitätsschichten kosten Ressourcen, die dann für die eigentliche Arbeit fehlen." } },
  "3.2.3|3.8.2": { rel: "support",
    support: { en: "Scalability is the ability to change the capacity: a scalable product reaches a higher maximum by adding resources.",
               de: "Skalierbarkeit ist die Fähigkeit, die Kapazität zu verändern: Ein skalierbares Produkt erreicht mit zusätzlichen Ressourcen einen höheren Höchstwert." } },
  "3.2.3|3.8.3": { rel: "support",
    support: { en: "Automated, fast installation makes it easy to add servers when more capacity is needed.",
               de: "Automatisierte, schnelle Installation macht es leicht, Server hinzuzufügen, wenn mehr Kapazität gebraucht wird." } },
  "3.2.3|3.8.4": { rel: "neutral",
    neutral: { en: "Hardly any direct link. A replacement must offer at least the same capacity, but replaceability itself does not change it.",
               de: "Kaum ein direkter Zusammenhang. Ein Ersatz muss mindestens dieselbe Kapazität bieten, die Austauschbarkeit selbst ändert sie aber nicht." } },
  "3.2.3|3.9.1": { rel: "neutral",
    neutral: { en: "Hardly any direct link. In some domains a safety limit caps the capacity on purpose, for example the maximum load of a lift.",
               de: "Kaum ein direkter Zusammenhang. In manchen Bereichen begrenzt eine Sicherheitsgrenze die Kapazität absichtlich, etwa die Höchstlast eines Aufzugs." } },
  "3.2.3|3.9.2": { rel: "neutral",
    neutral: { en: "Hardly any direct link. Overload can itself be a risk in safety-critical systems, so its identification should include the load.",
               de: "Kaum ein direkter Zusammenhang. In sicherheitskritischen Systemen kann Überlast selbst ein Risiko sein; die Risikoerkennung sollte die Last einbeziehen." } },
  "3.2.3|3.9.3": { rel: "neutral",
    neutral: { en: "Hardly any direct link. The safe state usually needs little capacity; it matters that enough is left to reach it under full load.",
               de: "Kaum ein direkter Zusammenhang. Der sichere Zustand braucht meist wenig Kapazität; wichtig ist, dass unter Volllast genug bleibt, um ihn zu erreichen." } },
  "3.2.3|3.9.4": { rel: "neutral",
    neutral: { en: "Hardly any direct link. A warning before a capacity limit is reached, for example a nearly full storage, is useful – but that is monitoring, not safety.",
               de: "Kaum ein direkter Zusammenhang. Eine Warnung vor dem Erreichen einer Kapazitätsgrenze, etwa bei fast vollem Speicher, ist nützlich – das ist aber Monitoring, nicht Safety." } },
  "3.2.3|3.9.5": { rel: "neutral",
    neutral: { en: "Hardly any direct link. A new component has to be checked for whether it keeps working safely at full load.",
               de: "Kaum ein direkter Zusammenhang. Bei einer neuen Komponente ist zu prüfen, ob sie auch unter Volllast sicher arbeitet." } }
};
